use std::collections::HashMap;

/// Returns one value whose last occurrence position is minimal among all values.
fn solve(cafes: Vec<i8>) -> i8 {
    assert!(!cafes.is_empty());

    // Map each value to its last index.
    let mut last: HashMap<i8, usize> = HashMap::new();
    for (i, &v) in cafes.iter().enumerate() {
        last.insert(v, i);
    }

    // Pick the value with the smallest last index.
    let mut best_val = cafes[0];
    let mut best_pos = *last.get(&best_val).unwrap();

    for (&v, &pos) in last.iter() {
        if pos < best_pos {
            best_pos = pos;
            best_val = v;
        }
    }

    best_val
}

